"""
Provide the creation of collector configuration for gNodeB with an all in cloud
deployment. For some specific components, like i.e. CPRT, CPNB, CPNRT, the syslog
log collector configurations are created.
"""

# pylint: disable=E1101


class CloudGnbSyslogCollectorConfigurator:
    """
    Configuration creation for syslog on all in cloud gNodeBs
    """

    def _create_vdu_component_syslog_collector(self, ne_log_name, du_id):
        """
        Creates all vdu specific collectors for syslog logs for the vdu identified by du_id

        :param str name: The name of the parent collector
        :param int du_id: The du id of the VDU (from testline configuration vdu list)
        """
        master_node = self.tl_config_information_provider.get_vdu_master_node_ssh_details(
            self.ne_id, vdu_id=du_id)
        namespace = self.tl_config_information_provider.get_vdu_namespace(
            node_id=self.ne_id, vdu_id=du_id)

        executor = {
            'host': master_node.addr,
            'user': master_node.username,
            'password': master_node.password}

        vdu_pods = self.k8s_information_provider.get_pods(node_id=self.ne_id, du_id=du_id)

        collector_names = []
        for vdu_pod in vdu_pods:
            collector_name = f'{ne_log_name}_du{du_id}_{vdu_pod}'

            k8s_collector_configuration = {
                'type': 'kubernetes',
                'name': collector_name,
                'namespace': namespace,
                'pod_name': vdu_pod,
                'merge_container_logs': True,
                'executor': executor}

            self._collector_configuration_data.append(k8s_collector_configuration)
            collector_names.append(collector_name)

        return collector_names

    def _create_cu_component_syslog_collector(self, ne_log_name):
        """
        Creates all collectors needed to get the syslog of all pods from a cu component.

        :param str name: The name of the parent collector
        :returns: The collector configuration dictionary for the taf.collector.kubernetes
        """

        master_node = self.tl_config_information_provider.get_cu_master_node_ssh_details(
            self.ne_id)

        executor = {
            'host': master_node.addr,
            'user': master_node.username,
            'password': master_node.password}

        cu_pods = self.k8s_information_provider.get_pods(node_id=self.ne_id)
        collector_names = []
        for cu_pod in cu_pods:
            collector_name = f'{ne_log_name}_{cu_pod}'

            k8s_collector_configuration = {
                'type': 'kubernetes',
                'name': collector_name,
                'namespace': self.tl_config_information_provider.get_cu_namespace(node_id=self.ne_id),
                'pod_name': cu_pod,
                'merge_container_logs': True,
                'executor': executor}

            self._collector_configuration_data.append(k8s_collector_configuration)
            collector_names.append(collector_name)

        return collector_names

    def add_syslog(self, ne_log_name, ne_log_configuration):
        """
        Creates for several components the collector configurations and appends them to
        the global collector configuration list of the builder.

        :param str ne_log_name: The name of the collector given in configuration
        :param dict ne_log_configuration: The trace type specific configuration dictionary
        """
        collector_members = []

        for du_id in self.tl_config_information_provider.get_du_ids(node_id=self.ne_id):
            vdu_collector_names = self._create_vdu_component_syslog_collector(ne_log_name, du_id)
            collector_members += vdu_collector_names

        cu_collector_names = self._create_cu_component_syslog_collector(ne_log_name)
        collector_members += cu_collector_names

        syslog_collector = {'type': 'group',
                            'name': f'{ne_log_name}',
                            'members': collector_members}

        self._collector_configuration_data.append(syslog_collector)

        self._collector_configuration_data.add_mapping_entry(
            log_type='syslog',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=syslog_collector)
